B.a2P=s(["\u062a\u062a\u0645 \u0639\u0645\u0644\u064a\u0629 \u0633\u062f\u0627\u062f \u0631\u0633\u0648\u0645 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643\u0627\u062a (\u0633\u0648\u0627\u0621 \u0644\u0644\u0639\u0645\u0644\u0627\u0621 \u0623\u0648 \u0645\u0632\u0648\u062f\u064a \u0627\u0644\u062e\u062f\u0645\u0627\u062a) \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0642\u0646\u0648\u0627\u062a \u0627\u0644\u0633\u062f\u0627\u062f \u0627\u0644\u0645\u062a\u0627\u062d\u0629 \u0648\u0627\u0644\u0645\u0639\u062a\u0645\u062f\u0629 \u0639\u0628\u0631 \u0627\u0644\u0645\u0646\u0635\u0629\u060c \u0648\u0627\u0644\u062a\u064a \u062a\u0648\u0641\u0631 \u0637\u0631\u0642 \u062f\u0641\u0639 \u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\u0629 \u0622\u0645\u0646\u0629 \u0648\u0645\u062a\u0648\u0627\u0641\u0642\u0629 \u0645\u0639 \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0627\u0644\u0628\u0646\u0643\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0645\u0644\u0643\u0629."],t.s)
B.aj1=new A.kJ("\u062b\u0627\u0644\u062b\u0627\u064b: \u0642\u0646\u0648\u0627\u062a \u0648\u0637\u0631\u0642 \u0627\u0644\u0633\u062f\u0627\u062f",B.a2P)
B.a_g=s(["1. \u0631\u0633\u0648\u0645 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u063a\u064a\u0631 \u0645\u0633\u062a\u0631\u062f\u0629: \u0643\u0627\u0641\u0629 \u0631\u0633\u0648\u0645 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643\u0627\u062a \u0627\u0644\u0645\u062f\u0641\u0648\u0639\u0629 (\u0633\u0648\u0627\u0621 \u0627\u0644\u0634\u0647\u0631\u064a\u0629 \u0623\u0648 \u0627\u0644\u062f\u0648\u0631\u064a\u0629 \u0623\u0648 \u0627\u0644\u0633\u0646\u0648\u064a\u0629) \u062a\u0639\u062a\u0628\u0631 \u0646\u0647\u0627\u0626\u064a\u0629 \u0648\u063a\u064a\u0631 \u0645\u0633\u062a\u0631\u062f\u0629 \u0628\u0645\u062c\u0631\u062f \u0625\u062a\u0645\u0627\u0645 \u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u062f\u0641\u0639 \u0648\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u062d\u0633\u0627\u0628.","2. \u062d\u0627\u0644\u0627\u062a \u062d\u0630\u0641 \u0623\u0648 \u0625\u064a\u0642\u0627\u0641 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643: \u064a\u062d\u0642 \u0644\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u0646\u0635\u0629 \u0623\u0648 \u0627\u0644\u0646\u0638\u0627\u0645 \u062d\u0630\u0641 \u0623\u0648 \u0625\u064a\u0642\u0627\u0641 \u062d\u0633\u0627\u0628/\u0627\u0634\u062a\u0631\u0627\u0643 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0641\u064a \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062a\u0627\u0644\u064a\u0629:","\u0639\u062f\u0645 \u062a\u062c\u062f\u064a\u062f \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643: \u0641\u064a \u062d\u0627\u0644 \u0639\u062f\u0645 \u062a\u062c\u062f\u064a\u062f \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u062e\u0644\u0627\u0644 (7 \u0623\u064a\u0627\u0645) \u0642\u0628\u0644 \u0627\u0646\u062a\u0647\u0627\u0621 \u0645\u062f\u0629 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u0627\u0644\u062d\u0627\u0644\u064a\u0629.","\u0631\u063a\u0628\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645: \u0628\u0646\u0627\u0621\u064b \u0639\u0644\u0649 \u0637\u0644\u0628 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 \u0646\u0641\u0633\u0647 \u0628\u062d\u0630\u0641 \u062d\u0633\u0627\u0628\u0647 \u0623\u0648 \u0625\u064a\u0642\u0627\u0641\u0647.","\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0634\u0643\u0627\u0648\u0649: \u0628\u0633\u0628\u0628 \u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u0634\u0643\u0627\u0648\u0649 \u0627\u0644\u0645\u0648\u062b\u0648\u0642\u0629 \u0636\u062f \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645 (\u0633\u0648\u0627\u0621 \u0645\u0646 \u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u0623\u0648 \u0645\u0632\u0648\u062f\u064a \u0627\u0644\u062e\u062f\u0645\u0627\u062a) \u0628\u0645\u0627 \u064a\u062a\u0639\u0627\u0631\u0636 \u0645\u0639 \u0645\u0639\u0627\u064a\u064a\u0631 \u062c\u0648\u062f\u0629 \u0648\u0623\u0645\u0627\u0646 \u0627\u0644\u0645\u0646\u0635\u0629."],t.s)
B.aj4=new A.kJ("\u0631\u0627\u0628\u0639\u0627\u064b: \u0623\u062d\u0643\u0627\u0645 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643\u0627\u062a \u0648\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u0627\u0633\u062a\u0631\u062c\u0627\u0639",B.a_g)
B.a_s=s(["\u0646\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0644\u0644\u0623\u063a\u0631\u0627\u0636 \u0627\u0644\u062a\u0627\u0644\u064a\u0629 \u0641\u0642\u0637:","1. \u062a\u0641\u0639\u064a\u0644 \u0648\u062a\u0634\u063a\u064a\u0644 \u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0648\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643\u0627\u062a.","2. \u0625\u062a\u0645\u0627\u0645 \u0639\u0645\u0644\u064a\u0629 \u0627\u0644\u0631\u0628\u0637 \u0627\u0644\u0641\u0648\u0631\u064a \u0648\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u0644\u0645\u0642\u062f\u0645 \u0627\u0644\u062e\u062f\u0645\u0629 \u0627\u0644\u0645\u0646\u0627\u0633\u0628 \u062c\u063a\u0631\u0627\u0641\u064a\u0627\u064b.","3. \u062a\u062d\u0633\u064a\u0646 \u062c\u0648\u062f\u0629 \u0627\u0644\u062e\u062f\u0645\u0629\u060c \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062f\u0639\u0645 \u0627\u0644\u0641\u0646\u064a\u060c \u0648\u0625\u0631\u0633\u0627\u0644 \u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a \u0648\u0627\u0644\u062a\u0646\u0628\u064a\u0647\u0627\u062a \u0627\u0644\u062e\u0627\u0635\u0629 \u0628\u0627\u0644\u0637\u0644\u0628\u0627\u062a.","4. \u0627\u0644\u0627\u0645\u062a\u062b\u0627\u0644 \u0644\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0646\u0638\u0627\u0645\u064a\u0629 \u0648\u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u0627\u0644\u0633\u0639\u0648\u062f\u064a\u0629."],t.s)
B.aj0=new A.kJ("\u062e\u0627\u0645\u0633\u0627\u064b: \u0627\u0644\u063a\u0631\u0636 \u0645\u0646 \u062c\u0645\u0639 \u0648\u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a",B.a_s)
B.a0P=s(["1. \u0628\u064a\u0646 \u0627\u0644\u0623\u0637\u0631\u0627\u0641 \u0627\u0644\u0645\u0639\u0646\u064a\u0629: \u064a\u062a\u0645 \u0645\u0634\u0627\u0631\u0643\u0629 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0648\u0627\u0644\u0645\u0648\u0642\u0639 \u0627\u0644\u062c\u063a\u0631\u0627\u0641\u064a \u0648\u0648\u0635\u0641 \u0627\u0644\u0637\u0644\u0628 \u0627\u0644\u062e\u0627\u0635 \u0628\u0627\u0644\u0639\u0645\u064a\u0644 \u062d\u0635\u0631\u064a\u0627\u064b \u0645\u0639 \xab\u0645\u0632\u0648\u062f \u0627\u0644\u062e\u062f\u0645\u0629\xbb \u0627\u0644\u0630\u064a \u062a\u0645 \u0642\u0628\u0648\u0644 \u0627\u0644\u0637\u0644\u0628 \u0645\u0646 \u0637\u0631\u0641\u0647 \u0644\u0625\u062a\u0645\u0627\u0645 \u0627\u0644\u062e\u062f\u0645\u0629.","2. \u0627\u0644\u062c\u0647\u0627\u062a \u0627\u0644\u0631\u0633\u0645\u064a\u0629: \u0644\u0627 \u0646\u0642\u0648\u0645 \u0628\u0628\u064a\u0639 \u0623\u0648 \u062a\u0623\u062c\u064a\u0631 \u0628\u064a\u0627\u0646\u0627\u062a\u0643\u060c \u0648\u0644\u0646 \u064a\u062a\u0645 \u0627\u0644\u0625\u0641\u0635\u0627\u062d \u0639\u0646\u0647\u0627 \u0625\u0644\u0627 \u0628\u0645\u0648\u062c\u0628 \u0627\u0644\u0623\u0646\u0638\u0645\u0629 \u0648\u0627\u0644\u0642\u0648\u0627\u0646\u064a\u0646 \u0627\u0644\u0645\u0631\u0639\u064a\u0629 \u0641\u064a \u0627\u0644\u0645\u0645\u0644\u0643\u0629 \u0623\u0648 \u0628\u0623\u0645\u0631 \u0642\u0636\u0627\u0626\u064a."],t.s)
